// Generates the inlinable engine block (fail-successfully + dispatch, no import/export)
// and injects it between // <ENGINE-BUNDLE:start> / <ENGINE-BUNDLE:end> markers in each TARGET.
//
// A target may ALSO declare an extras block: a module inlined into that target ALONE, under its
// own marker pair. This is how librarian-specific pure helpers reach the sandbox without being
// duplicated into orchestration-audit.workflow.mjs, where they would be dead code.
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const LIB = new URL('./lib/', import.meta.url);
const TARGETS = ['./orchestration-audit.workflow.mjs', './librarian.workflow.mjs'];
const START = '// <ENGINE-BUNDLE:start>';
const END = '// <ENGINE-BUNDLE:end>';

export const EXTRAS = {
  './librarian.workflow.mjs': { name: 'LIBRARIAN-CORE', module: 'librarian-core.mjs' },
};

// The marker strings are interpolated into `new RegExp` in inject(), so a name containing a regex
// metacharacter would silently change matching semantics instead of failing. That is the exact
// failure class this module refuses to allow: a broken extras injection cannot be caught by
// `engine:check`, because a skipped injection produces no git diff. So constrain the name and
// throw — loud beats clever.
const EXTRAS_NAME_RE = /^[A-Z0-9-]+$/;

export function extrasMarkers(name) {
  if (!EXTRAS_NAME_RE.test(name)) {
    throw new Error(`EXTRAS name ${JSON.stringify(name)} must match ${EXTRAS_NAME_RE} — it is interpolated into a RegExp`);
  }
  return { start: `// <${name}:start>`, end: `// <${name}:end>` };
}

// NOTE: source files must NOT use `export default` — the strip regex below would corrupt it.
function strip(src) {
  return src
    .replace(/^\s*import\s+\{[\s\S]*?\}\s+from\s+['"]\.\/fail-successfully\.mjs['"];?\s*$/m, '')
    .replace(/^export\s+/gm, '');          // `export function` → `function`, `export const` → `const`
}

export async function buildBundle() {
  const engine = strip(await readFile(new URL('fail-successfully.mjs', LIB), 'utf8'));
  const dispatch = strip(await readFile(new URL('dispatch.mjs', LIB), 'utf8'));
  const verify = strip(await readFile(new URL('verify.mjs', LIB), 'utf8'));
  if (/^\s*import\s/m.test(engine) || /^\s*import\s/m.test(dispatch) || /^\s*import\s/m.test(verify)) {
    throw new Error('strip() left a bare import — add a strip rule for the new import');
  }
  return `${START}\n// GENERATED by scripts/build-engine-bundle.mjs — do not edit; run \`npm run build:engine\`.\n${engine}\n${dispatch}\n${verify}\n${END}`;
}

/**
 * Build the per-target extras block, or null when the target declares none.
 * @param {string} relPath - a key of TARGETS
 * @returns {Promise<string|null>}
 */
export async function buildExtras(relPath) {
  const spec = EXTRAS[relPath];
  if (!spec) return null;
  const src = strip(await readFile(new URL(spec.module, LIB), 'utf8'));
  if (/^\s*import\s/m.test(src)) {
    throw new Error(`strip() left a bare import in ${spec.module} — extras modules must have no imports`);
  }
  const { start, end } = extrasMarkers(spec.name);
  return `${start}\n// GENERATED by scripts/build-engine-bundle.mjs from lib/${spec.module} — do not edit; run \`npm run build:engine\`.\n${src}\n${end}`;
}

async function inject(block, relPath, start, end) {
  const url = new URL(relPath, import.meta.url);
  const file = fileURLToPath(url);
  const src = await readFile(file, 'utf8');
  const re = new RegExp(`${start}[\\s\\S]*?${end}`);
  if (!re.test(src)) throw new Error(`markers not found in ${relPath}`);
  await writeFile(file, src.replace(re, block));
}

if (process.argv.includes('--emit')) {
  const block = await buildBundle();
  for (const t of TARGETS) {
    try { await inject(block, t, START, END); } catch (e) { console.error(`skip ${t}: ${e.message}`); }
  }
  // Extras injection does NOT swallow a missing-marker error. A skipped engine block leaves a stale
  // but working bundle; a skipped extras block leaves the consumer calling helpers that are not
  // there. `engine:check` would still pass, because git sees no diff — so the failure must be loud
  // here or it is invisible everywhere.
  for (const t of Object.keys(EXTRAS)) {
    const extras = await buildExtras(t);
    const { start, end } = extrasMarkers(EXTRAS[t].name);
    await inject(extras, t, start, end);
  }
}
